import{_ as i,a0 as o,w as r,s as d,ao as p,I as t,x as a,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"通过“猜数字”游戏学习 Tcl | LCTT x X-CMD","titleTemplate":false,"description":"通过“猜数字”游戏学习 Tcl | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过“猜数字”游戏学习 Tcl | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过“猜数字”游戏学习 Tcl | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230209.3 ⭐️⭐️ Learn Tcl by writing a simple game","title":"通过“猜数字”游戏学习 Tcl","tag":"202302","desc":""},"relativePath":"202302/20230209.3 ⭐️⭐️ Learn Tcl by writing a simple game.md","filePath":"[post].md"}'),c={name:"202302/20230209.3 ⭐️⭐️ Learn Tcl by writing a simple game.md"};function g(u,s,h,b,k,m){const n=o("Link");return r(),d("div",null,[s[24]||(s[24]=p(`<h1 id="通过-猜数字-游戏学习-tcl" tabindex="-1">通过“猜数字”游戏学习 Tcl <a class="header-anchor" href="#通过-猜数字-游戏学习-tcl" aria-label="Permalink to “通过“猜数字”游戏学习 Tcl”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/23/140000ilg3oa8khgrhr1r3.jpg" alt=""></p><blockquote><p>探索 Tcl 的基本语言结构，包括用户输入、输出、变量、条件评估、循环和简单函数。</p></blockquote><p>我的 Tcl 之旅始于最近需要将一个困难的基于 Java 的命令行配置工具自动化。我使用 Ansible 做了一些自动化编程，偶尔也会使用 <code>expect</code> 模块。坦率地说，我发现这个模块的作用有限，原因包括：难以对相同的提示进行排序，难以捕捉到额外步骤的值，控制逻辑的灵活性有限，等等。有时你可以用 <code>shell</code> 模块来代替。但有时你会遇到那种特立独行、过于复杂的命令行程序，似乎无法实现自动化。</p><p>就我而言，我正在自动安装我公司的一个程序。最后的配置步骤只能通过命令行来完成，通过几个不规范的、重复的提示和需要捕捉的数据输出。好在传统的 Expect 是唯一的答案。要使用 Expect 的基本功能，并不需要对 Tcl 有很深的了解，但你了解的越多，你就能从它那里得到更多的力量。这是后续文章的话题。现在，我探讨一下 Tcl 的基本语言结构，包括用户输入、输出、变量、条件判断、循环和简单函数。</p><h3 id="安装-tcl" tabindex="-1">安装 Tcl <a class="header-anchor" href="#安装-tcl" aria-label="Permalink to “安装 Tcl”">​</a></h3><p>在 Linux 系统上，我使用这个：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install tcl</span></span>
<span class="line"><span># which tclsh</span></span>
<span class="line"><span>/bin/tclsh</span></span></code></pre></div>`,8)),t("p",null,[s[1]||(s[1]=a("在 macOS 上，你可以使用 ",-1)),e(n,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:l(()=>[...s[0]||(s[0]=[a("Homebrew",-1)])]),_:1}),s[2]||(s[2]=a(" 来安装最新的 Tcl：",-1))]),s[25]||(s[25]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install tcl-tk</span></span>
<span class="line"><span>$ which tclsh</span></span>
<span class="line"><span>/usr/local/bin/tclsh</span></span></code></pre></div><h3 id="在-tcl-中猜数字" tabindex="-1">在 Tcl 中猜数字 <a class="header-anchor" href="#在-tcl-中猜数字" aria-label="Permalink to “在 Tcl 中猜数字”">​</a></h3><p>从创建基本的可执行脚本 <code>numgame.tcl</code> 开始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch numgame.tcl</span></span>
<span class="line"><span>$ chmod 755 numgame.tcl</span></span></code></pre></div><p>接着在你的文件中开始编码，标题是通常的 #!：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/tclsh</span></span></code></pre></div><p>这里有一些关于 Tcl 的简单介绍，以便与本文一起追踪。</p><p>第一点是，Tcl 处理的都是字符串。变量通常被当作字符串处理，但可以自动切换类型和内部表示（这一点你通常无法看到）。函数可以把它们的字符串参数解释为数字（<code>expr</code>），并且只通过值传递。字符串通常使用双引号或大括号来划分。双引号允许变量扩展和转义序列，而大括号则完全没有扩展。</p><p>第二点是 Tcl 语句可以用分号隔开，但通常不这样。语句行可以用反斜杠字符来分割，然而，典型的做法是将多行语句放在大括号内，以避免需要这样做。大括号只是更简单，下面的代码格式也反映了这一点。大括号允许对字符串进行延迟求值。在 Tcl 进行变量替换之前，值被传递给函数。</p><p>最后，Tcl 使用方括号进行命令替换。方括号之间的任何东西都会被送到 Tcl 解释器的一个新的递归调用中进行求值。这对于在表达式中间调用函数或为函数生成参数是很方便的。</p><h3 id="过程" tabindex="-1">过程 <a class="header-anchor" href="#过程" aria-label="Permalink to “过程”">​</a></h3><p>虽然在这个游戏中没有必要，但我先举一个在 Tcl 中定义函数的例子，你可以在以后使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>proc used_time {start} {</span></span>
<span class="line"><span>	return [expr [clock seconds] - $start]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用 <code>proc</code> 将其设定为一个函数（或过程）定义。接下来是函数的名称。然后是一个包含参数的列表；在本例中是一个参数 <code>{start}</code> ，然后是函数主体。注意，主体的大括号在这一行开始，它不能在下面一行。该函数返回一个值。返回值是一个复合求值（方括号），它从读取系统时钟 <code>[clock seconds]</code> 开始，并进行数学运算以减去 <code>$start</code> 参数。</p><h3 id="设置、逻辑和完成" tabindex="-1">设置、逻辑和完成 <a class="header-anchor" href="#设置、逻辑和完成" aria-label="Permalink to “设置、逻辑和完成”">​</a></h3><p>你可以在这个游戏的其余部分增加更多的细节，进行一些初始设置，对玩家的猜测进行迭代，然后在完成后打印结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set num [expr round(rand()*100)]</span></span>
<span class="line"><span>set starttime [clock seconds]</span></span>
<span class="line"><span>set guess -1</span></span>
<span class="line"><span>set count 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>puts &quot;Guess a number between 1 and 100&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while { $guess != $num } {</span></span>
<span class="line"><span>	incr count</span></span>
<span class="line"><span>	puts -nonewline &quot;==&gt; &quot;</span></span>
<span class="line"><span>	flush stdout</span></span>
<span class="line"><span>	gets stdin guess</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	if { $guess &lt; $num } {</span></span>
<span class="line"><span>		puts &quot;Too small, try again&quot;</span></span>
<span class="line"><span>	} elseif { $guess &gt; $num } {</span></span>
<span class="line"><span>		puts &quot;Too large, try again&quot;</span></span>
<span class="line"><span>	} else {</span></span>
<span class="line"><span>		puts &quot;That&#39;s right!&quot;</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set used [used_time $starttime]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>puts &quot;You guessed value $num after $count tries and $used elapsed seconds&quot;</span></span></code></pre></div><p>前面的 <code>set</code> 语句建立变量。前两个求值表达式用于识别 1 到 100 之间的随机数，下一个保存系统时钟启动时间。</p><p><code>puts</code> 和 <code>gets</code> 命令用于来自玩家的输出和输入。我使用的 <code>puts</code> 暗示输出是标准输出。<code>gets</code> 需要定义输入通道，所以这段代码指定 <code>stdin</code> 作为用户的终端输入源。</p><p>当 <code>puts</code> 省略行末终止符时，需要 <code>flush stdout</code> 命令，因为 Tcl 缓冲了输出，在需要下一个 I/O 之前可能不会被显示。</p><p>从这里开始，<code>while</code> 语句说明了循环控制结构和条件逻辑，需要给玩家反馈并最终结束循环。</p><p>最后的 <code>set</code> 命令调用我们的函数来计算游戏的耗时秒数，接着是收集到的统计数字来结束游戏。</p><h3 id="玩吧" tabindex="-1">玩吧! <a class="header-anchor" href="#玩吧" aria-label="Permalink to “玩吧!”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./numgame.tcl</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>==&gt; 100</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 50</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 25</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 12</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 6</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 3</span></span>
<span class="line"><span>That&#39;s right!</span></span>
<span class="line"><span>You guessed value 3 after 6 tries and 20 elapsed seconds</span></span></code></pre></div><h3 id="继续学习" tabindex="-1">继续学习 <a class="header-anchor" href="#继续学习" aria-label="Permalink to “继续学习”">​</a></h3>`,25)),t("p",null,[s[4]||(s[4]=a("当我开始这个练习时，我怀疑回到 90 年代末的流行语言对我有多大的帮助。一路走来，我发现 Tcl 有几处让我非常喜欢的地方，我最喜欢的是方括号内的命令求值。与其他许多过度使用复杂闭包结构的语言相比，它似乎更容易阅读和使用。我以为它是一种 ",-1)),e(n,{href:"https://opensource.com/article/19/6/favorite-dead-language"},{default:l(()=>[...s[3]||(s[3]=[a("已消亡的语言",-1)])]),_:1}),s[5]||(s[5]=a("，但实际上它仍在蓬勃发展，并在多个平台上得到支持。我学到了一些新的技能，并对这种古老的语言有了新的认识。",-1))]),t("p",null,[s[7]||(s[7]=a("在 ",-1)),e(n,{href:"https://www.tcl-lang.org"},{default:l(()=>[...s[6]||(s[6]=[a("https://www.tcl-lang.org",-1)])]),_:1}),s[8]||(s[8]=a(" 上查看官方网站。你可以找到最新的源代码、二进制发行版、论坛、文档，以及仍在进行的会议信息的参考。",-1))]),s[26]||(s[26]=t("hr",null,null,-1)),t("p",null,[s[10]||(s[10]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/23/2/learn-tcl-writing-simple-game"},{default:l(()=>[...s[9]||(s[9]=[a("https://opensource.com/article/23/2/learn-tcl-writing-simple-game",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jamesf"},{default:l(()=>[...s[11]||(s[11]=[a("James Farrell",-1)])]),_:1}),s[16]||(s[16]=a(" 选题：",-1)),e(n,{href:"https://github.com/lkxed/"},{default:l(()=>[...s[12]||(s[12]=[a("lkxed",-1)])]),_:1}),s[17]||(s[17]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:l(()=>[...s[13]||(s[13]=[a("geekpi",-1)])]),_:1}),s[18]||(s[18]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[21]||(s[21]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...s[20]||(s[20]=[a("Linux中国",-1)])]),_:1}),s[23]||(s[23]=a(" 荣誉推出",-1))])])}const y=i(c,[["render",g]]);export{x as __pageData,y as default};
